mapper.update:
UPDATE parts
code = #{code}, name = #{name}, specs = #{specs}, location_id = #{locationId}, location = #{location}, amount = #{amount}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, parts_id, code, name, specs, amount, location_id, location, status, movement_date, remark, create_by, create_time
FROM parts_record

    AND name LIKE CONCAT('%', #{name}, '%')
    AND location_id = #{locationId}
    AND status = #{status}
    AND movement_date >= #{startDate}
    AND movement_date <= #{endDate}

ORDER BY create_time DESC
